// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title WorldCupBetting
 * @dev Monad üzerinde 2026 Dünya Kupası bahis kontratı
 * Commission: %2 (0.02)
 */
contract WorldCupBetting is Ownable, ReentrancyGuard {

    // ==================== Types ====================
    enum BetStatus { Pending, Won, Lost, Cancelled }
    enum MatchStatus { Scheduled, Ongoing, Completed, Cancelled }

    struct Match {
        uint256 id;
        string teamA;
        string teamB;
        uint8 scoreA;
        uint8 scoreB;
        MatchStatus status;
        uint256 createdAt;
        address winnerId; // null address if draw
    }

    struct Bet {
        uint256 id;
        address bettor;
        uint256 matchId;
        string selectedTeam; // "TeamA", "TeamB", or "DRAW"
        uint256 amount;
        uint256 odds; // Stored as odds * 100 (e.g., 1.8x = 180)
        BetStatus status;
        uint256 potentialWinning;
        uint256 actualWinning;
        uint256 createdAt;
        uint256 resolvedAt;
    }

    struct BookmakerStats {
        uint256 totalBetsReceived;
        uint256 totalPayouts;
        uint256 totalCommission;
        int256 netProfit;
    }

    // ==================== State Variables ====================

    mapping(uint256 => Match) public matches;
    mapping(uint256 => Bet) public bets;
    mapping(address => uint256[]) public userBets;

    uint256 public matchCounter = 0;
    uint256 public betCounter = 0;

    uint256 public constant COMMISSION_PERCENTAGE = 2; // %2
    uint256 public constant ODDS_MULTIPLIER = 100; // odds * 100

    uint256 public totalBetsReceived = 0;
    uint256 public totalPayouts = 0;
    uint256 public totalCommission = 0;

    // ==================== Events ====================

    event MatchCreated(uint256 indexed matchId, string teamA, string teamB);
    event BetPlaced(uint256 indexed betId, address indexed bettor, uint256 matchId, string team, uint256 amount, uint256 odds);
    event BetResolved(uint256 indexed betId, BetStatus status, uint256 payout);
    event MatchFinalized(uint256 indexed matchId, string winner, uint8 scoreA, uint8 scoreB);
    event CommissionWithdrawn(address indexed owner, uint256 amount);

    // ==================== Constructor ====================

    constructor() Ownable(msg.sender) {}

    // ==================== Match Management ====================

    /**
     * @dev Maç oluştur
     */
    function createMatch(string memory _teamA, string memory _teamB) external onlyOwner {
        matches[matchCounter] = Match({
            id: matchCounter,
            teamA: _teamA,
            teamB: _teamB,
            scoreA: 0,
            scoreB: 0,
            status: MatchStatus.Scheduled,
            createdAt: block.timestamp,
            winnerId: address(0)
        });

        emit MatchCreated(matchCounter, _teamA, _teamB);
        matchCounter++;
    }

    /**
     * @dev Maç skoru güncelle
     */
    function updateMatchScore(uint256 _matchId, uint8 _scoreA, uint8 _scoreB) external onlyOwner {
        require(_matchId < matchCounter, "Match not found");
        require(matches[_matchId].status == MatchStatus.Scheduled || 
                matches[_matchId].status == MatchStatus.Ongoing, "Match cannot be updated");

        matches[_matchId].scoreA = _scoreA;
        matches[_matchId].scoreB = _scoreB;
        matches[_matchId].status = MatchStatus.Ongoing;
    }

    /**
     * @dev Maçı tamamla ve bahisleri çöz
     */
    function finalizeMatch(uint256 _matchId, address _winnerId) external onlyOwner nonReentrant {
        require(_matchId < matchCounter, "Match not found");
        require(matches[_matchId].status == MatchStatus.Ongoing || 
                matches[_matchId].status == MatchStatus.Scheduled, "Match already completed");

        Match storage matchData = matches[_matchId];
        matchData.status = MatchStatus.Completed;
        matchData.winnerId = _winnerId;

        string memory winner = _winnerId == address(0) ? "DRAW" : matchData.teamA; // Simplified
        emit MatchFinalized(_matchId, winner, matchData.scoreA, matchData.scoreB);

        // Resolve all bets for this match
        resolveBetsForMatch(_matchId);
    }

    // ==================== Betting Functions ====================

    /**
     * @dev Bahis yap
     */
    function placeBet(
        uint256 _matchId,
        string memory _selectedTeam,
        uint256 _odds
    ) external payable nonReentrant {
        require(_matchId < matchCounter, "Match not found");
        require(msg.value > 0, "Bet amount must be greater than 0");
        require(matches[_matchId].status == MatchStatus.Scheduled, "Match is not available for betting");
        require(_odds >= 105 && _odds <= 350, "Invalid odds (1.05x - 3.5x)"); // odds * 100

        uint256 potentialWinning = (msg.value * _odds) / ODDS_MULTIPLIER;

        Bet storage newBet = bets[betCounter];
        newBet.id = betCounter;
        newBet.bettor = msg.sender;
        newBet.matchId = _matchId;
        newBet.selectedTeam = _selectedTeam;
        newBet.amount = msg.value;
        newBet.odds = _odds;
        newBet.status = BetStatus.Pending;
        newBet.potentialWinning = potentialWinning;
        newBet.createdAt = block.timestamp;

        userBets[msg.sender].push(betCounter);
        totalBetsReceived += msg.value;

        emit BetPlaced(betCounter, msg.sender, _matchId, _selectedTeam, msg.value, _odds);
        betCounter++;
    }

    /**
     * @dev Belirli bir maç için tüm bahisleri çöz
     */
    function resolveBetsForMatch(uint256 _matchId) internal {
        Match storage matchData = matches[_matchId];

        for (uint256 i = 0; i < betCounter; i++) {
            if (bets[i].matchId == _matchId && bets[i].status == BetStatus.Pending) {
                resolveSingleBet(i, matchData);
            }
        }
    }

    /**
     * @dev Tek bir bahis çöz
     */
    function resolveSingleBet(uint256 _betId, Match storage matchData) internal {
        Bet storage bet = bets[_betId];

        bool betWon = false;

        // Determine if bet won
        if (matchData.scoreA == matchData.scoreB) {
            // Draw
            betWon = keccak256(abi.encodePacked(bet.selectedTeam)) == keccak256(abi.encodePacked("DRAW"));
        } else if (matchData.scoreA > matchData.scoreB) {
            // Team A wins
            betWon = keccak256(abi.encodePacked(bet.selectedTeam)) == keccak256(abi.encodePacked(matchData.teamA));
        } else {
            // Team B wins
            betWon = keccak256(abi.encodePacked(bet.selectedTeam)) == keccak256(abi.encodePacked(matchData.teamB));
        }

        if (betWon) {
            // Bet won: Calculate payout with %2 commission
            uint256 grossWinning = bet.potentialWinning;
            uint256 commission = (grossWinning * COMMISSION_PERCENTAGE) / 100;
            uint256 actualWinning = grossWinning - commission;

            bet.status = BetStatus.Won;
            bet.actualWinning = actualWinning;
            bet.resolvedAt = block.timestamp;

            totalPayouts += actualWinning;
            totalCommission += commission;

            // Transfer winnings to bettor
            (bool success, ) = payable(bet.bettor).call{value: actualWinning}("");
            require(success, "Transfer failed");

            emit BetResolved(_betId, BetStatus.Won, actualWinning);
        } else {
            // Bet lost
            bet.status = BetStatus.Lost;
            bet.actualWinning = 0;
            bet.resolvedAt = block.timestamp;

            emit BetResolved(_betId, BetStatus.Lost, 0);
        }
    }

    /**
     * @dev Bahis iptal et (eğer maç scheduled ise)
     */
    function cancelBet(uint256 _betId) external nonReentrant {
        require(_betId < betCounter, "Bet not found");
        require(bets[_betId].bettor == msg.sender, "Only bettor can cancel");
        require(bets[_betId].status == BetStatus.Pending, "Bet already resolved");
        require(matches[bets[_betId].matchId].status == MatchStatus.Scheduled, "Cannot cancel bet for ongoing/completed match");

        uint256 refundAmount = bets[_betId].amount;
        bets[_betId].status = BetStatus.Cancelled;
        totalBetsReceived -= refundAmount;

        (bool success, ) = payable(msg.sender).call{value: refundAmount}("");
        require(success, "Refund failed");
    }

    // ==================== View Functions ====================

    /**
     * @dev Bookmaker istatistikleri
     */
    function getBookmakerStats() external view returns (BookmakerStats memory) {
        int256 netProfit = int256(totalBetsReceived) - int256(totalPayouts);

        return BookmakerStats({
            totalBetsReceived: totalBetsReceived,
            totalPayouts: totalPayouts,
            totalCommission: totalCommission,
            netProfit: netProfit
        });
    }

    /**
     * @dev Kullanıcı bahislerini getir
     */
    function getUserBets(address _user) external view returns (uint256[] memory) {
        return userBets[_user];
    }

    /**
     * @dev Bet detayları getir
     */
    function getBetDetails(uint256 _betId) external view returns (Bet memory) {
        require(_betId < betCounter, "Bet not found");
        return bets[_betId];
    }

    /**
     * @dev Match detayları getir
     */
    function getMatchDetails(uint256 _matchId) external view returns (Match memory) {
        require(_matchId < matchCounter, "Match not found");
        return matches[_matchId];
    }

    /**
     * @dev Kullanıcının belirli bir bahsini getir
     */
    function getUserBetCount(address _user) external view returns (uint256) {
        return userBets[_user].length;
    }

    // ==================== Admin Functions ====================

    /**
     * @dev Komisyon çek
     */
    function withdrawCommission() external onlyOwner nonReentrant {
        uint256 commissionAmount = totalCommission;
        totalCommission = 0;

        (bool success, ) = payable(owner()).call{value: commissionAmount}("");
        require(success, "Withdrawal failed");

        emit CommissionWithdrawn(owner(), commissionAmount);
    }

    /**
     * @dev Kontrat bakiyesini getir
     */
    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @dev Acil durum para çekme
     */
    function emergencyWithdraw() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "Emergency withdrawal failed");
    }

    // ==================== Receive Ether ====================

    receive() external payable {}
}
